func main() {
    change, err := settle(7, 10)
    fmt.Println(change, err)
}

func settle(price, paid int64) (int64, error) {
    if price <= 0 {
        return 0, ErrInvalidPrice
    }
    if paid < price {
        return 0, ErrInsufficientPayment
    }
    return paid - price, nil
}

