    handle CapabilityHandle, cmd CanonicalCommand,
) (ArtifactRef, error) {
    expected := ExpectedState{
        LeaseOwner: claim.LeaseOwner, Fence: claim.Fence,
        StepVersion: claim.StepVersion,
        GrantVersion: claim.ApprovalVersion,
        CancelRequested: false,
